engine.polishAnalyze:
async function polishAnalyze(input, providers) {
  var original = String((input && input.text) || "");
  var instruction = String((input && input.instruction) || "").trim();
  if (!original.trim()) {
    throw new Error("Nothing selected to polish.");
  }

  // ── Deterministic preservation check ─────────────────────────────────
  // Facts that MUST survive a meaning-preserving rewrite. Deliberately
  // high-signal only — exact tokens plus one structural test — because a
  // noisy guard trains people to ignore it.
  function _collect(s) {
    var out = [];
    function add(re, capIdx) {
      var m;
      re.lastIndex = 0;
      while ((m = re.exec(s)) !== null) {
        var v = capIdx != null ? m[capIdx] : m[0];
        if (v && String(v).trim()) out.push(String(v).trim());
        if (m.index === re.lastIndex) re.lastIndex++;
      }
    }
    // Proper thousands grouping — [\d,]+ would swallow a trailing comma
    // ("$50,000," from "…up to $50,000, except…") and then never match the
    // rewrite, producing a false "missing" on a perfectly good variant.
    add(/\$\s?\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?/g);                       // money
    add(/\b\d+(?:\.\d+)?\s?(?:%|percent)\b/gi);                          // percentages
    add(/\b(?:Section|Article|Exhibit|Schedule|Appendix|Annex|Clause)\s+[A-Za-z0-9][A-Za-z0-9.\-]*/g); // cross-refs
    add(/\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4}\b/g); // dates
    add(/\b\d{1,3}(?:,\d{3})+\b/g);                                      // thousand-separated numbers
    add(/[“"]([^”"\n]{2,60})[”"]/g, 1);                                  // quoted defined terms (inner text)
    return out;
  }
  function _norm(s) {
    return String(s)
      .replace(/[“”]/g, '"')
      .replace(/[‘’]/g, "'")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  }
  // A dropped proviso is the dangerous silent failure (the rewrite reads
  // cleaner precisely because the carve-out is gone). Structural test:
  // original had exception language, rewrite has none at all.
  var EXCEPTION_RE = /\b(provided\s+that|provided,?\s*however|except|unless|excluding|other than|shall not apply|does not apply|save for|subject to|but not)\b/i;

  function _preservationCheck(orig, variant) {
    var missing = [];
    var vn = _norm(variant);
    var seen = {};
    // Longest first, then drop any token contained in one already kept —
    // otherwise "$50,000" and "50,000" both report the same missing fact.
    var toks = _collect(orig).slice().sort(function (a, b) { return b.length - a.length; });
    var kept = [];
    toks.forEach(function (tok) {
      var key = _norm(tok);
      if (!key || seen[key]) return;
      for (var k = 0; k < kept.length; k++) {
        if (kept[k].indexOf(key) !== -1) return;   // substring of a longer token
      }
      seen[key] = true;
      kept.push(key);
      if (vn.indexOf(key) === -1) missing.push(tok);
    });
    var lostProviso = EXCEPTION_RE.test(orig) && !EXCEPTION_RE.test(variant);
    return {
      ok: missing.length === 0 && !lostProviso,
      missing: missing,
      lostProviso: lostProviso,
    };
  }

  function _words(s) {
    var t = String(s || "").trim();
    return t ? t.split(/\s+/).filter(Boolean).length : 0;
  }

  // ── Prompt ───────────────────────────────────────────────────────────
  var prompt =
    "You are polishing a passage from a professional or legal document. Rewrite it THREE times.\n\n" +
    "ABSOLUTE RULE — PRESERVE MEANING EXACTLY. Never add, remove, weaken or broaden an obligation, " +
    "condition, exception, carve-out, party, amount, date, defined term or cross-reference. You are " +
    "improving the WRITING, never the substance. Every proviso in the original must survive in all three.\n\n" +
    "Produce these three registers, in this order:\n" +
    '  1. "Polished" — the same passage written well: better flow, no throat-clearing, run-ons split.\n' +
    '  2. "Plainer"  — everyday wording, direct and readable, identical obligations.\n' +
    '  3. "Formal"   — measured professional register, traditional drafting conventions, precise.\n\n' +
    (instruction
      ? ("USER INSTRUCTION — apply to all three: " + instruction + "\n\n")
      : "") +
    "Each version must be a GENUINE rewrite — restructure sentences where it helps readability. " +
    "Do not merely swap one or two words. Keep the same number of paragraphs as the original and " +
    "separate paragraphs with a newline (\\n).\n\n" +
    "Return ONLY a JSON array, no markdown:\n" +
    '[{"label":"Polished","why":"<6 words max on what you changed>","text":"<the rewrite>"},' +
    '{"label":"Plainer","why":"...","text":"..."},{"label":"Formal","why":"...","text":"..."}]\n\n' +
    "PASSAGE:\n\"\"\"\n" + original + "\n\"\"\"";

  // Writing is not deep reasoning — a small budget keeps Polish snappy.
  var raw = await providers.ai.completeJSON(prompt, null, {
    thinkingBudget: 512,
    strict: true,
    signal: input && input.signal,
  });

  var list = Array.isArray(raw)
    ? raw
    : (raw && Array.isArray(raw.versions) ? raw.versions : []);

  var origWords = _words(original);
  var variants = list.map(function (v) {
    var text = String((v && v.text) || "").trim();
    return {
      label: String((v && v.label) || "").trim() || "Polished",
      why: String((v && v.why) || "").trim(),
      text: text,
      words: _words(text),
      originalWords: origWords,
      check: _preservationCheck(original, text),
    };
  }).filter(function (v) {
    // A rewrite identical to the input is not a rewrite. (Same lesson as
    // error_review's no-op findings — never surface a do-nothing option.)
    return v.text && _norm(v.text) !== _norm(original);
  });

  var toolVer = "unknown";
  try {
    if (typeof window !== "undefined" && window.eli && window.eli.tools &&
        window.eli.tools._loaded && window.eli.tools._loaded["polish"]) {
      toolVer = window.eli.tools._loaded["polish"].releasedAt || "unknown";
    }
  } catch (e) { /* tolerate */ }

  return {
    items: variants,
    overview: variants.length
      ? variants.length + " polished version(s) of " + origWords + " words."
      : "No usable rewrite was produced.",
    _meta: { original: original, instruction: instruction },
    provenance: {
      kernelVersion: (typeof window !== "undefined" && window.eli) ? window.eli.kernelVersion : "node",
      toolVersion: toolVer,
      promptVersion: "polish@v1",
      model: (typeof window !== "undefined" && window.eli && window.eli.ai &&
              typeof window.eli.ai.getModel === "function") ? window.eli.ai.getModel() : null,
      docHash: (input && input.docHash) || null,
      timestamp: Date.now(),
    },
  };
}

view.renderPolishWorkspace:
function renderPolishWorkspace(opts) {
  opts = opts || {};
  var host = opts.host;
  if (!host) return null;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function _el(tag, css, text) {
    var e = document.createElement(tag);
    if (css) e.style.cssText = css;
    if (text != null) e.textContent = text;
    return e;
  }
  // Word-level LCS diff — a rewrite needs real alignment; prefix/suffix
  // diffing would just strike the whole passage and re-add it.
  function _diffHtml(oldS, newS) {
    var A = String(oldS).match(/\S+|\s+/g) || [];
    var B = String(newS).match(/\S+|\s+/g) || [];
    var n = A.length, m = B.length;
    if (n * m > 400000) return _esc(newS);
    var dp = [], i, j;
    for (i = 0; i <= n; i++) { dp.push(new Array(m + 1).fill(0)); }
    for (i = n - 1; i >= 0; i--) {
      for (j = m - 1; j >= 0; j--) {
        dp[i][j] = (A[i] === B[j]) ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
      }
    }
    var out = ""; i = 0; j = 0;
    while (i < n && j < m) {
      if (A[i] === B[j]) { out += _esc(A[i]); i++; j++; }
      else if (dp[i + 1][j] >= dp[i][j + 1]) { out += '<span class="_pl_del">' + _esc(A[i]) + "</span>"; i++; }
      else { out += '<span class="_pl_add">' + _esc(B[j]) + "</span>"; j++; }
    }
    while (i < n) { out += '<span class="_pl_del">' + _esc(A[i++]) + "</span>"; }
    while (j < m) { out += '<span class="_pl_add">' + _esc(B[j++]) + "</span>"; }
    return out;
  }

  var PROSE = "font:400 15px/1.72 Georgia,'Times New Roman',serif;color:#111827;padding:9px 12px;margin:4px 12px 0;border:1px solid transparent;border-radius:3px;outline:none;white-space:pre-wrap;";
  var LAB = "font:800 9px/1 Inter,'Segoe UI',system-ui,sans-serif;text-transform:uppercase;letter-spacing:.15em;color:#0f172a;";
  var WHY = "font:400 11px/1.4 Inter,'Segoe UI',system-ui,sans-serif;color:#6b7280;";
  var LINK = "font:600 10.5px/1 Inter,'Segoe UI',system-ui,sans-serif;color:#64748b;background:none;border:none;cursor:pointer;padding:9px 4px;";
  var USE = "font:800 10px/1 Inter,'Segoe UI',system-ui,sans-serif;letter-spacing:.08em;text-transform:uppercase;padding:9px 18px;border:1px solid #0f3d2e;background:linear-gradient(180deg,#16794f,#0f5c3b);color:#fff;cursor:pointer;";

  host.innerHTML = "";
  var root = _el("div", "background:#fafafa;border:1px solid #e5e7eb;font-family:Inter,'Segoe UI',system-ui,sans-serif;");
  root.className = "_pl_root";
  host.appendChild(root);

  // ── Header ───────────────────────────────────────────────────────────
  var hdr = _el("div", "padding:15px 18px 13px;border-bottom:1px solid #ececec;background:#fff;display:flex;align-items:baseline;justify-content:space-between;gap:10px;");
  hdr.appendChild(_el("div", "font:800 16px/1.2 Inter,system-ui,sans-serif;color:#111827;", "✨ Polish"));
  var meta = _el("div", "font:500 11px/1 Inter,system-ui,sans-serif;color:#9ca3af;",
    (opts.wordCount || 0) + " words selected");
  hdr.appendChild(meta);
  root.appendChild(hdr);

  var body = _el("div", "padding:16px 18px 18px;");
  root.appendChild(body);

  // ── Original (quiet reference) ───────────────────────────────────────
  var origWrap = _el("div", "margin-bottom:18px;padding-left:11px;border-left:2px solid #e5e7eb;");
  origWrap.appendChild(_el("div", LAB + "color:#9ca3af;margin-bottom:6px;", "Your text"));
  origWrap.appendChild(_el("div",
    "font:400 13.5px/1.65 Georgia,'Times New Roman',serif;color:#9ca3af;white-space:pre-wrap;",
    opts.original || ""));
  body.appendChild(origWrap);

  var hint = _el("div", "font:500 10.5px/1 Inter,system-ui,sans-serif;color:#9ca3af;margin-bottom:9px;",
    "Click any version to edit it directly.");
  body.appendChild(hint);

  var listEl = _el("div", "");
  body.appendChild(listEl);

  // ── Steer + regenerate ───────────────────────────────────────────────
  var steer = _el("div", "background:#fff;border:1px solid #e5e7eb;padding:11px 12px;margin-bottom:12px;");
  var instrInput = document.createElement("input");
  instrInput.type = "text";
  instrInput.placeholder = "Tell Polish what to change — e.g. “shorter and less apologetic”";
  instrInput.value = opts.instruction || "";
  instrInput.style.cssText = "width:100%;box-sizing:border-box;font:400 12.5px/1.5 Inter,system-ui,sans-serif;color:#111827;border:none;outline:none;padding:4px 2px 9px;background:transparent;";
  steer.appendChild(instrInput);
  var regenBtn = _el("button", "width:100%;padding:11px;font:800 11px/1 Inter,system-ui,sans-serif;letter-spacing:.09em;text-transform:uppercase;color:#334155;background:linear-gradient(180deg,#ffffff,#eef2f6);border:1px solid #cbd5e1;cursor:pointer;", "↻  Regenerate");
  regenBtn.type = "button";
  steer.appendChild(regenBtn);
  body.appendChild(steer);

  // ── Footer ───────────────────────────────────────────────────────────
  var foot = _el("div", "display:flex;align-items:center;justify-content:space-between;gap:10px;");
  var guardLine = _el("span", "font:500 10.5px/1.4 Inter,system-ui,sans-serif;color:#9ca3af;", "");
  foot.appendChild(guardLine);
  var trackLabel = _el("label", "display:flex;align-items:center;gap:6px;font:500 10.5px/1 Inter,system-ui,sans-serif;color:#6b7280;cursor:pointer;");
  var trackCb = document.createElement("input");
  trackCb.type = "checkbox";
  trackCb.style.cssText = "accent-color:#c9a227;width:14px;height:14px;";
  trackLabel.appendChild(trackCb);
  trackLabel.appendChild(document.createTextNode("Insert as tracked change"));
  foot.appendChild(trackLabel);
  body.appendChild(foot);

  regenBtn.onclick = function () {
    if (typeof opts.onRegenerate === "function") opts.onRegenerate(instrInput.value || "");
  };

  // ── Variant cards ────────────────────────────────────────────────────
  function _card(v, idx) {
    var edited = false;
    var card = _el("div", "background:#fff;border:1px solid #e5e7eb;margin-bottom:14px;" +
      (idx === 0 ? "border-top:2px solid #c9a227;" : ""));

    var head = _el("div", "padding:13px 12px 0;display:flex;align-items:baseline;gap:9px;");
    head.appendChild(_el("span", LAB, v.label));
    if (v.why) head.appendChild(_el("span", WHY, v.why));
    head.appendChild(_el("span", "font:600 10px/1 Inter,system-ui,sans-serif;color:#9ca3af;margin-left:auto;",
      (v.originalWords || 0) + " → " + (v.words || 0)));
    card.appendChild(head);

    var prose = _el("div", PROSE);
    prose.className = "_pl_prose";
    prose.setAttribute("contenteditable", "true");
    prose.setAttribute("spellcheck", "true");
    prose.textContent = v.text;
    card.appendChild(prose);

    // Diff pane (hidden until requested)
    var diffPane = _el("div", PROSE + "display:none;cursor:default;background:#fcfcfd;border-color:#eceff3;");
    diffPane.setAttribute("contenteditable", "false");
    card.appendChild(diffPane);

    // Preservation warning — loud ONLY when something actually went missing
    if (v.check && !v.check.ok) {
      var bits = [];
      if (v.check.lostProviso) bits.push("an exception/proviso");
      if (v.check.missing && v.check.missing.length) bits.push(v.check.missing.slice(0, 4).join(", "));
      var warn = _el("div",
        "margin:8px 12px 0;padding:8px 10px;background:#fef2f2;border:1px solid #fecaca;font:600 10.5px/1.45 Inter,system-ui,sans-serif;color:#b91c1c;",
        "⚠ Missing from the original: " + bits.join(" · ") + ". Review before inserting.");
      card.appendChild(warn);
    }

    var actions = _el("div", "display:flex;align-items:center;gap:8px;padding:6px 12px 12px;");
    var useBtn = _el("button", USE, "Use this");
    useBtn.type = "button";
    var copyBtn = _el("button", LINK, "Copy");
    copyBtn.type = "button";
    var diffBtn = _el("button", LINK, "Show changes");
    diffBtn.type = "button";
    var revertBtn = _el("button", LINK + "margin-left:auto;color:#b45309;display:none;", "↺ Revert my edits");
    revertBtn.type = "button";
    actions.appendChild(useBtn);
    actions.appendChild(copyBtn);
    actions.appendChild(diffBtn);
    actions.appendChild(revertBtn);
    card.appendChild(actions);

    prose.addEventListener("input", function () {
      if (!edited) {
        edited = true;
        revertBtn.style.display = "";
        prose.style.background = "#fffdf7";
        prose.style.borderColor = "#eadfae";
      }
    });
    revertBtn.onclick = function () {
      prose.textContent = v.text;
      edited = false;
      revertBtn.style.display = "none";
      prose.style.background = "";
      prose.style.borderColor = "transparent";
    };
    diffBtn.onclick = function () {
      var showing = diffPane.style.display !== "none";
      if (showing) {
        diffPane.style.display = "none";
        prose.style.display = "";
        diffBtn.textContent = "Show changes";
      } else {
        diffPane.innerHTML = _diffHtml(opts.original || "", prose.textContent || "");
        diffPane.style.display = "";
        prose.style.display = "none";
        diffBtn.textContent = "Hide changes";
      }
    };
    copyBtn.onclick = function () {
      var txt = prose.textContent || "";
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(txt);
        } else if (window._eliClipboardWriteOrFallback) {
          window._eliClipboardWriteOrFallback(txt);
        }
        copyBtn.textContent = "Copied ✓";
        setTimeout(function () { copyBtn.textContent = "Copy"; }, 1400);
      } catch (e) { /* tolerate */ }
    };
    useBtn.onclick = function () {
      if (typeof opts.onUse !== "function") return;
      useBtn.disabled = true;
      useBtn.textContent = "Inserting…";
      Promise.resolve()
        .then(function () {
          return opts.onUse(prose.textContent || "", !!trackCb.checked, v);
        })
        .then(function () {
          useBtn.textContent = "Inserted ✓";
          useBtn.style.background = "#e8f5e9";
          useBtn.style.color = "#166534";
          useBtn.style.borderColor = "#a5d6a7";
        })
        .catch(function (err) {
          useBtn.disabled = false;
          useBtn.textContent = "⚠ Failed";
          if (typeof showToast === "function") {
            showToast("Insert failed: " + ((err && err.message) || "unknown"), "err");
          }
        });
    };
    return card;
  }

  function setVariants(variants) {
    listEl.innerHTML = "";
    var arr = variants || [];
    if (!arr.length) {
      listEl.appendChild(_el("div",
        "padding:18px;background:#fff;border:1px solid #e5e7eb;font:500 12.5px/1.6 Inter,system-ui,sans-serif;color:#6b7280;",
        "No usable rewrite came back. Try Regenerate, or add an instruction above."));
      guardLine.textContent = "";
      return;
    }
    arr.forEach(function (v, i) { listEl.appendChild(_card(v, i)); });
    var bad = arr.filter(function (v) { return v.check && !v.check.ok; }).length;
    guardLine.textContent = bad
      ? ("⚠ " + bad + " of " + arr.length + " dropped something from the original")
      : ("✓ Meaning preserved in all " + arr.length);
    guardLine.style.color = bad ? "#b91c1c" : "#9ca3af";
  }

  function setBusy(on, msg) {
    regenBtn.disabled = !!on;
    regenBtn.textContent = on ? (msg || "↻  Polishing…") : "↻  Regenerate";
    if (on) {
      listEl.innerHTML = "";
      var sk = _el("div", "padding:18px;background:#fff;border:1px solid #e5e7eb;");
      [80, 96, 62].forEach(function (w) {
        sk.appendChild(_el("div", "height:11px;width:" + w + "%;background:#eef2f6;margin-bottom:9px;animation:_plPulse 1.1s ease-in-out infinite;"));
      });
      sk.appendChild(_el("div", "font:600 10px/1 Inter,system-ui,sans-serif;color:#9aa6b2;margin-top:6px;", msg || "Polishing…"));
      listEl.appendChild(sk);
      guardLine.textContent = "";
    }
  }

  return { setVariants: setVariants, setBusy: setBusy, getInstruction: function () { return instrInput.value || ""; } };
}

jsonTools.init:
function init(eli) {
  var _busy = false;

  // Capture the selection AND bookmark it, so the insert still lands after
  // the user has clicked around the taskpane and lost the live selection.
  function _readSelection() {
    return eli.host.runRaw("polish:read-selection", function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () {
        var text = String(sel.text || "");
        if (!text.trim()) return { text: "" };
        // Bookmark names MUST begin with a letter — Word silently rejects
        // non-letter-leading names (insertBookmark becomes a no-op).
        var name = "ELI_POLISH_" + Date.now();
        try { sel.insertBookmark(name); } catch (e) { name = ""; }
        return context.sync().then(function () {
          return { text: text, bookmark: name };
        });
      });
    });
  }

  function _insert(bookmark, newText, tracked) {
    return eli.host.runRaw("polish:insert", async function (context) {
      var prior = null;
      try {
        context.document.load("changeTrackingMode");
        await context.sync();
        prior = context.document.changeTrackingMode || null;
      } catch (e) { /* older builds — tolerate */ }
      var target = tracked ? "TrackAll" : "Off";
      try {
        context.document.changeTrackingMode = target;
        await context.sync();   // flush BEFORE the insert, or it lands in the old mode
      } catch (e) { /* tolerate */ }
      try {
        var range = null;
        if (bookmark) {
          range = context.document.getBookmarkRangeOrNullObject(bookmark);
          range.load("isNullObject");
          await context.sync();
          if (range.isNullObject) range = null;
        }
        if (!range) range = context.document.getSelection();
        range.insertText(newText, "Replace");
        await context.sync();
      } finally {
        if (prior != null && prior !== target) {
          try {
            context.document.changeTrackingMode = prior;
            await context.sync();
          } catch (e) { /* tolerate */ }
        }
      }
    });
  }

  function _notice(host, text) {
    host.innerHTML = "";
    var d = document.createElement("div");
    d.style.cssText = "padding:22px 20px;background:#fff;border:1px solid #e5e7eb;" +
      "font:500 13px/1.65 Inter,'Segoe UI',system-ui,sans-serif;color:#6b7280;";
    d.textContent = text;
    host.appendChild(d);
  }

  async function showPolish() {
    if (_busy) return;
    var host = (eli.ui && typeof eli.ui.claimOutput === "function")
      ? eli.ui.claimOutput()
      : document.getElementById("output");
    if (!host) return;

    var sel = null;
    try { sel = await _readSelection(); } catch (e) { sel = null; }
    if (!sel || !String(sel.text || "").trim()) {
      _notice(host, "Select the text you want to polish in the document, then click Polish again.");
      return;
    }

    // Word uses \r for paragraph marks; normalise for display + the AI, and
    // convert back on insert so paragraph breaks survive the round trip.
    var original = String(sel.text).replace(/\r\n?/g, "\n").trim();
    var wordCount = original.split(/\s+/).filter(Boolean).length;

    var ui = renderPolishWorkspace({
      host: host,
      original: original,
      wordCount: wordCount,
      onUse: function (text, tracked) {
        var outText = String(text || "").replace(/\n/g, "\r");
        return _insert(sel.bookmark, outText, tracked).then(function () {
          try { if (eli.stats) eli.stats.record("polishApplied"); } catch (e) {}
          try {
            if (eli.activity && typeof eli.activity.add === "function") {
              eli.activity.add({
                type: "polish", icon: "✨", label: "Polish applied",
                summary: wordCount + " words rewritten" + (tracked ? " (tracked)" : ""),
                timestamp: Date.now(),
              });
            }
          } catch (e) {}
          try { if (eli.host && typeof eli.host.invalidateCache === "function") eli.host.invalidateCache(); } catch (e) {}
        });
      },
      onRegenerate: function (instruction) { _run(instruction); },
    });

    function _run(instruction) {
      _busy = true;
      ui.setBusy(true, "Polishing…");
      Promise.resolve()
        .then(function () {
          return polishAnalyze(
            { text: original, instruction: instruction },
            { ai: eli.ai, host: eli.host }
          );
        })
        .then(function (res) {
          ui.setBusy(false);
          ui.setVariants((res && res.items) || []);
        })
        .catch(function (err) {
          ui.setBusy(false);
          ui.setVariants([]);
          if (typeof showToast === "function") {
            showToast("Polish failed: " + ((err && err.message) || "unknown"), "err");
          }
        })
        .then(function () { _busy = false; });
    }

    _run("");
  }

  eli.register({
    tile: { app_polish: showPolish },
    // Cross-tool entry point — Ask ELI's "Polish Text" button dispatches this.
    polish: { open: showPolish },
  });
}

